    expect(parseArgs(['build', '--incremental']).incremental).toBe(true);
    expect(parseArgs(['build', '--clean']).clean).toBe(true);
    expect(parseArgs(['build']).incremental).toBe(false);
    expect(parseArgs(['build']).clean).toBe(false);
  });
});

